public async Task<ExchangeRate> GetRate(string pair, CancellationToken ct)
{
    // 1) Serve recent data if the breaker is open or the call would timeout
    if (_breaker.State == CircuitState.Open && _cache.TryGetValue(pair, out var stale))
        return stale;                       // deliberately stale beats unavailable

    try
    {
        using var cts = CancellationTokenSource.CreateLinkedTokenSource(ct);
        cts.CancelAfter(TimeSpan.FromMilliseconds(300));  // budget-bounded

        var fresh = await _http.GetFromJsonAsync<ExchangeRate>(
            $"/rates/{pair}", cts.Token);

        _cache.Set(pair, fresh, TimeSpan.FromMinutes(5));
        return fresh;
    }
    catch (Exception ex) when (ex is TaskCanceledException or HttpRequestException)
    {
        _breaker.OnFailure();                                  // trips after threshold
        if (_cache.TryGetValue(pair, out var cached))
            return cached;                                      // degraded but functional
        throw new DependencyUnavailableException("rates", ex);
    }
}
